import { Component, EventEmitter, Input, Output } from '@angular/core';

@Component({
  selector: 'app-confirm-modal',
  templateUrl: './confirm-modal.component.html',
  styleUrls: ['./confirm-modal.component.css']
})
export class ConfirmModalComponent {
  @Input() isOpen = false;
  @Input() title = 'Confirm Action';
  @Input() message = 'Are you sure you want to proceed? This action cannot be undone.';
  @Input() confirmText = 'Confirm';
  @Input() cancelText = 'Cancel';
  @Input() isDanger = false;
  @Input() isLoading = false;

  @Output() confirm = new EventEmitter<void>();
  @Output() cancel = new EventEmitter<void>();

  onConfirm(): void {
    if (!this.isLoading) {
      this.confirm.emit();
    }
  }

  onCancel(): void {
    if (!this.isLoading) {
      this.cancel.emit();
    }
  }
}
<div class="modal-backdrop" *ngIf="isOpen" (click)="onCancel()">
  <div class="modal-dialog" (click)="$event.stopPropagation()">
    <div class="modal-header">
      <div class="modal-icon-badge" [ngClass]="isDanger ? 'badge-danger' : 'badge-primary'">
        <i [class]="isDanger ? 'fa-solid fa-triangle-exclamation' : 'fa-solid fa-circle-question'"></i>
      </div>
      <h3 class="modal-title">{{ title }}</h3>
      <button class="modal-close-btn" (click)="onCancel()" aria-label="Close dialog">
        <i class="fa-solid fa-xmark"></i>
      </button>
    </div>

    <div class="modal-body">
      <p class="modal-message">{{ message }}</p>
    </div>

    <div class="modal-footer">
      <button type="button" class="btn btn-secondary" (click)="onCancel()" [disabled]="isLoading">
        {{ cancelText }}
      </button>
      <button
        type="button"
        class="btn"
        [ngClass]="isDanger ? 'btn-danger' : 'btn-primary'"
        (click)="onConfirm()"
        [disabled]="isLoading">
        <i *ngIf="isLoading" class="fa-solid fa-spinner spinner"></i>
        {{ isLoading ? 'Processing...' : confirmText }}
      </button>
    </div>
  </div>
</div>
